        final steps = job['steps'] as YamlList;
        final checkout = steps
            .map((s) => s as YamlMap)
            .firstWhere((s) => s['uses']?.toString().startsWith('actions/checkout') ?? false);
        expect(checkout['with']['token']?.toString(),
