  group('AC6 — regression', () {
    test('no "Release vX" filler bodies remain', () {
      final haystacks = [
        ...workflows.map(read),
        read('scripts/auto_release.sh'),
        read('scripts/tag_release.sh'),
      ];
      for (final text in haystacks) {
