  final sweep = jobsOf('.github/workflows/daily-publish.yml')['sweep-drafts'] as YamlMap;
  final perms = sweep['permissions'];
  if (perms is! YamlMap || perms.isEmpty) return '';
  return perms.keys.map((k) => k.toString()).join(' ');
}

