+            .toString()
+      });
+  git(['tag', 'v0.1.495']);
+  File('$seed/README.md').writeAsStringSync('pending\n');
+  git(['add', '-A']);
+  git(['commit', '-q', '-m', 'pending work']);
+  git(['push', '-q', 'origin', 'main']);
+  if (staleBranch) {
+    final c1 = Process.runSync('git', ['rev-list', '--max-parents=0', 'HEAD'],
+            workingDirectory: seed)
